const {chromium} = require('playwright');
(async () => {
  const b = await chromium.launch({channel:'chrome', headless:true});
  const p = await b.newPage({viewport:{width:900,height:700}});
  await p.goto('file:///Users/sinchunyeung/github/simplification-of-trajectory-streams/web/usability/option-playback-label.html');
  const check = await p.textContent('#check');
  console.log('fixture', check);

  await p.setViewportSize({width:900, height:800});
  await p.goto('file:///Users/sinchunyeung/github/simplification-of-trajectory-streams/web/index.html');
  const captions = await p.evaluate(() => {
    const longs = [...document.querySelectorAll('.pb-caption-long')].map(e => e.textContent);
    const shorts = [...document.querySelectorAll('.pb-caption-short')].map(e => e.textContent);
    return {longs, shorts};
  });
  const gloss = await p.locator('#playbackInstructionsGloss').innerText();
  const statusGloss = await p.locator('#statusGloss').innerText();
  const mobileOpt = await p.locator('#mobileCandidateForwardBtn span').innerText();
  const overlay = await p.evaluate(() => {
    const fSi = document.querySelector('#toggle-F-Si')?.closest('label');
    const pMark = document.querySelector('#toggle-P')?.closest('label');
    return {
      fSi: {text: fSi?.innerText?.trim(), title: fSi?.title},
      markers: {text: pMark?.innerText?.trim(), title: pMark?.title},
    };
  });
  const userFacingCandidate = await p.evaluate(() => {
    const bodyText = document.body.innerText;
    // Ignore script/id names; check visible text for Candidate as a control word
    const hits = [];
    if (bodyText.includes('Candidate')) hits.push('body.innerText');
    for (const el of document.querySelectorAll('[title],[aria-label]')) {
      const t = (el.getAttribute('title') || '') + ' ' + (el.getAttribute('aria-label') || '');
      if (/\bCandidate\b/.test(t)) hits.push((el.id || el.tagName) + ':' + t.slice(0,80));
    }
    return hits;
  });
  const scroll = await p.evaluate(() => document.documentElement.scrollWidth);
  console.log(JSON.stringify({captions, glossHasOption: gloss.includes('Option') && !gloss.includes('Candidate'), statusHasOption: statusGloss.includes('Option') && !statusGloss.includes('Candidate'), mobileOpt, overlay, userFacingCandidate, scroll}, null, 2));

  // Narrow 820px: Opt short caption visible
  await p.setViewportSize({width:820, height:800});
  await p.waitForTimeout(100);
  const narrow = await p.evaluate(() => {
    const short = document.querySelectorAll('.pb-caption-short')[2];
    const long = document.querySelectorAll('.pb-caption-long')[2];
    const csShort = short ? getComputedStyle(short).display : null;
    const csLong = long ? getComputedStyle(long).display : null;
    return {shortText: short?.textContent, longText: long?.textContent, csShort, csLong, scroll: document.documentElement.scrollWidth};
  });
  console.log('narrow820', narrow);
  await b.close();
})().catch(e => { console.error(e); process.exit(1); });
"
